import {safAirports,checkedOn} from './airports.mjs';
import {countryName,directoryCsvRows,toCsv} from './directory.mjs';
import {initSupplier,renderSupplierResults,getSupplier,restoreSupplier,resetSupplier} from './supplier-ui.mjs';
import {initTracker,startTracker,stopTracker} from './tracker-ui.mjs';
import {initCompliance,renderComplianceResults,getCompliance,restoreCompliance,resetCompliance} from './compliance-ui.mjs';
import {gallons,toDisplay,fromDisplay,isVolume,isPrice,GALLONS_PER_TONNE} from './units.mjs';
import {tradeoffDefaults,optimizeTradeoff} from './tradeoff.mjs';
import {fallbackDefaults,compareFallback} from './fallback.mjs';
import {demoState,applyScenario,plan,formatHour} from './engine.mjs';
import {fitNetwork,greatCircle,distanceKm,flatPath} from './geo.mjs';
import {WORLD_LAND,WORLD_BORDERS,SCALE as WORLD_SCALE} from './worldmap.mjs';
import {placeLabels,textWidth} from './labels.mjs';
import {LAND,BORDERS,GRATICULE} from './basemap.mjs';
let fallback=fallbackDefaults(),tradeoff=tradeoffDefaults();
let state=demoState(),result,selected=null,lastFocus=null,selectedFlight='R101',mapLayer='flights';
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const num=(n,d=0)=>n.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const vol=(n,d=0)=>num(gallons(n),d);
const rate=n=>'$'+num(n/GALLONS_PER_TONNE,2);
const volumeText=text=>String(text).replace(/([0-9]+(?:\.[0-9]+)?) t(?!CO)/g,(_,n)=>vol(Number(n))+' US gal');
const money=n=>(n<0?'−$':'$')+num(Math.abs(n)), short=n=>n>=1000000?'$'+num(n/1000000,2)+'m':'$'+num(n/1000)+'k';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusClass=s=>s==='Commit'?'commit':s==='Keep flexible'?'flexible':s==='Split plan'?'split':'unallocated';
const hazards=['Not configured','Stable conditions','Smoke advisory','Strong headwinds','Thunderstorms','Hurricane disruption','Crosswinds','Storm escalation'];
const bounds={supply:[0,2000],price:[1,20000],ci:[0,300],risk:[0,100],delivery:[0,100],wind:[0,200],demand:[0,2000],need:[24,47],lead:[0,72],freight:[0,10000],capacity:[0,2000],baseline:[1,300],lhv:[1,60],target:[0,2000],enroute:[0,100],depart:[24,47],duration:[1,18]};

function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
const tabLabels={overview:'Overview',routes:'Routes',economics:'Cost & GHG',supply:'Supply & Constraints',airports:'SAF Airports',supplier:'Supplier Plan',compliance:'Compliance Plan',tracker:'Live Flights',method:'Methodology'};
let activeTab='overview';
function changeTab(id,scroll=true){
 if(!tabLabels[id])id='overview';activeTab=id;
 $$('.tab-panel').forEach(p=>p.hidden=p.id!==id);
 $$('.section-tab').forEach(b=>{const on=b.dataset.tab===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});
 $('#breadcrumb').textContent=tabLabels[id];$('.editorial-hero').hidden=id!=='overview';$('.landing-explainer').hidden=id!=='overview';
 $('.workspace-title h2').textContent={overview:'Tomorrow’s decisions. A clearer view.',routes:'Routes & destination risk',economics:'Cost & GHG decisions',supply:'Supply & delivery constraints',airports:'US & European SAF airports',supplier:'Supplier allocation & credit value',compliance:'Airline SAF & carbon compliance',tracker:'Live flights & SAF impact',method:'How the planner works'}[id];
 if(id==='supply'||id==='routes')renderInputs();
 if(id==='airports')renderDirectory();
 if(id==='supplier')renderSupplierResults();
 if(id==='compliance')renderComplianceResults();
 if(id==='tracker')startTracker();else stopTracker();
 if(id==='method'){ $('#baseline').value=state.baseline;$('#lhv').value=state.lhv; }
 history.replaceState(null,'','#'+id);
 if(scroll)$('#planning-workspace').scrollIntoView({behavior:'auto',block:'start'});
}

function syncControls(){for(const k of ['budget','flex','tolerance','review'])$('#'+k).value=state[k];$('#scenario').value=state.scenario;$('#plan-date').value=state.date;$('#baseline').value=state.baseline;$('#lhv').value=state.lhv}
function recalc(){result=plan(state);renderOverview();if(selected)renderDrawer()}

function renderOverview(){
  $('#budget-value').textContent=short(state.budget);$('#flex-value').textContent=state.flex+'%';$('#tolerance-value').textContent=state.tolerance+'%';
  const metrics=[['Commit now',vol(result.firm),'US gal SAF',`${result.rows.filter(r=>r.firm>0).length} airports · ${short(result.cost)} planned purchase`,'↗',''],['Keep flexible',vol(result.hold),'US gal SAF',`${short(result.holdCost)} budget ring-fenced · not ordered`,'⇄',''],['Expected savings',num(result.expected,1),'tCO₂e','Firm only · probability-weighted for tomorrow','◌','highlight'],['Budget headroom',short(result.remainingBudget),'',`${short(result.cost+result.holdCost)} allocated to firm + holds`,'◷','']];
  $('#metrics').innerHTML=metrics.map(m=>`<div class="metric ${m[5]}"><div class="metric-label">${m[0]}<span class="symbol">${m[4]}</span></div><div class="number">${m[1]}<span class="unit">${m[2]}</span></div><p>${m[3]}</p></div>`).join('');
  renderRouteFocus();
  renderFallback();
  renderFlightRows();
  renderMap();
  const high=result.flightRows.filter(r=>r.routeRisk>state.tolerance);const late=result.flightRows.filter(r=>r.firm+r.hold<.01);
  $('#insight').innerHTML=`<span class="insight-icon">↳</span><div><b>${result.firm>0?`Commit ${vol(result.firm)} US gal across ${result.rows.filter(r=>r.firm>0).length} airports.`:'No firm commitments under these constraints.'}</b> ${result.hold>0?`Keep ${vol(result.hold)} US gal conditional until ${formatHour(state.review)}.`:'No feasible conditional holds at the selected review time.'} ${high.length?` ${high.length} route group${high.length===1?' exceeds':'s exceed'} the firm risk threshold.`:''} ${late.length?` ${late.length} route group${late.length===1?'':'s'} currently unallocated.`:''}</div>`;
  $('#allocation-rows').innerHTML=result.rows.map(a=>`<tr tabindex="0" role="button" aria-label="Inspect ${a.id} recommendation" data-airport="${a.id}"><td><div class="airport-cell"><span class="airport-code">${a.id}</span><span class="outlook">${safe(a.name)}<small>${safe(a.hazard)} · ${a.wind} kt</small></span></div></td><td><span class="risk"><i class="risk-dot ${a.risk>40?'high':a.risk>20?'medium':''}"></i>${a.risk}%</span></td><td class="num">${a.firm>0?vol(a.firm)+' US gal':'<span class="muted">—</span>'}</td><td class="num">${a.hold>0?vol(a.hold)+' US gal':'<span class="muted">—</span>'}</td><td class="num">${num(a.expected,1)} <span class="muted">tCO₂e</span></td><td><span class="status ${statusClass(a.status)}">${a.status}</span></td><td class="row-arrow">↗</td></tr>`).join('');
  $('#supply-bars').innerHTML=state.suppliers.map(v=>{const ls=result.lanes.filter(l=>l.supplier===v.id),firm=ls.reduce((s,l)=>s+l.firm,0),hold=ls.reduce((s,l)=>s+l.hold,0);return `<div class="supplier-bar"><div class="bar-label"><b>${v.name}</b><span>${vol(firm+hold)} / ${vol(v.supply)} US gal</span></div><div class="bar"><span class="firm" style="width:${v.supply?firm/v.supply*100:0}%"></span><span class="hold" style="width:${v.supply?hold/v.supply*100:0}%"></span></div><div class="bar-caption">${vol(firm)} US gal firm · ${vol(hold)} US gal conditional · ${vol(result.supply[v.id])} US gal unassigned</div></div>`}).join('');
  const windows=result.flightRows.flatMap(f=>f.allocations.filter(a=>a.kind==='hold').map(a=>({...a,airport:f.origin,hold:a.quantity,route:f.origin+' → '+f.destination}))).sort((a,b)=>a.deadline-b.deadline);
  $('#windows').innerHTML=windows.length?windows.map(l=>`<div class="window"><i class="window-dot"></i><span class="time">${formatHour(l.deadline)}</span><div><strong>${l.route} · release ${vol(l.hold)} US gal by this time</strong><small>${state.suppliers.find(v=>v.id===l.supplier).name} · for this outbound route</small></div></div>`).join(''):`<div class="window"><div><strong>No conditional release windows</strong><small>Adjust reassessment time, supply, or budget to explore alternatives.</small></div></div>`;
}

function renderMap(){
  const network=fitNetwork([...state.airports,...state.suppliers]);
  const project=network.project,W={x:4,y:4,w:842,h:384};
  // Domestic: Albers equal-area US basemap. Extended (US + Europe): fitted overview with Natural Earth outlines.
  const xy=o=>{const [x,y]=project(o.lon,o.lat);return {x,y};};
  const polyline=pts=>pts.map(([lon,lat],i)=>{const [x,y]=project(lon,lat);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`;}).join('');
  const ll=o=>[o.lon,o.lat];
  const configured=a=>a.hazard!=='Not configured';
  const weather=result.rows.filter(a=>configured(a)&&a.risk>=30).map(a=>{const {x,y}=xy(a);return `<circle cx="${x}" cy="${y}" r="${(20+a.risk*0.9).toFixed(0)}" fill="url(#storm)"/>`;}).join('');
  const routes=result.lanes.map(l=>{const v=state.suppliers.find(s=>s.id===l.supplier),a=state.airports.find(a=>a.id===l.airport);const p=xy(v),q=xy(a);const c=l.firm>0?'#0876aa':l.hold>0?'#bd9c66':'#d6dae4';const dx=q.x-p.x,dy=q.y-p.y,cx=(p.x+q.x)/2-dy*.12,cy=(p.y+q.y)/2+dx*.12;const km=distanceKm(ll(v),ll(a));return `<path d="M${p.x.toFixed(1)},${p.y.toFixed(1)} Q${cx.toFixed(1)},${cy.toFixed(1)} ${q.x.toFixed(1)},${q.y.toFixed(1)}" fill="none" stroke="${c}" stroke-width="${l.firm+l.hold>0?1.5+Math.min(2,(l.firm+l.hold)/40):1}" stroke-dasharray="${l.hold>0&&l.firm===0?'6 5':l.firm+l.hold===0?'3 6':'none'}" opacity="${l.firm+l.hold>0?.85:.6}"><title>${safe(v.name)} (${safe(v.place||v.location)}) → ${a.id} · ${num(km,0)} km straight-line · ${l.lead} h transit</title></path>`;}).join('');
  const flightArcs=result.flightRows.map(f=>{const a=state.airports.find(a=>a.id===f.origin),b=state.airports.find(a=>a.id===f.destination);const c=f.firm>0?'#0876aa':f.hold>0?'#bd9c66':'#a3adb7';const km=distanceKm(ll(a),ll(b));return `<path data-flight="${f.id}" class="flight-arc" d="${polyline(greatCircle(ll(a),ll(b),40))}" fill="none" stroke="${c}" stroke-width="${f.id===selectedFlight?4:1.8}" stroke-dasharray="${f.firm>0?'none':'7 5'}" marker-end="url(#flight-arrow)" opacity="${f.id===selectedFlight?1:.45}"><title>${safe(f.airline)} · ${f.origin} → ${f.destination} · ${num(km,0)} km great circle · ${f.status}</title></path>`;}).join('');
  // Labels: airports first, then hubs, then ocean names; nothing may sit on a marker or another label.
  const pts=result.rows.map(a=>({a,...xy(a)})),hubPts=state.suppliers.map(v=>({v,...xy(v)}));
  const markerBoxes=[...pts.map(p=>({x:p.x-11,y:p.y-11,w:22,h:22})),...(mapLayer==='flights'?[]:hubPts.map(p=>({x:p.x-8,y:p.y-8,w:16,h:16})))];
  const sub=a=>configured(a)?a.risk+'% disruption':'Risk not configured';
  const airportBoxes=placeLabels(pts.map(p=>({x:p.x,y:p.y,w:Math.max(textWidth(p.a.id,15,true),textWidth(sub(p.a),13)),h:32})),markerBoxes,W);
  const hubBoxes=mapLayer==='flights'?[]:placeLabels(hubPts.map(p=>({x:p.x,y:p.y,w:textWidth(p.v.id.toUpperCase()+' HUB',12)+8,h:14,gap:10})),[...markerBoxes,...airportBoxes],W);
  const nodes=pts.map(({a,x,y},i)=>{const b=airportBoxes[i];const c=a.firm>0?'#0876aa':a.hold>0?'#bb965c':'#ad9b8e';return `<g class="airport-node" tabindex="0" role="button" aria-label="${a.id}, ${a.status}, inspect details" data-airport="${a.id}"><title>${a.id} · ${safe(a.name)} · ${Math.abs(a.lat).toFixed(2)}°${a.lat>=0?'N':'S'} ${Math.abs(a.lon).toFixed(2)}°${a.lon>=0?'E':'W'}</title><circle cx="${x}" cy="${y}" r="20" fill="${c}" opacity=".08"/><circle class="node-ring" cx="${x}" cy="${y}" r="8" fill="white" stroke="${c}" stroke-width="2"/><circle cx="${x}" cy="${y}" r="3" fill="${c}"/><text x="${b.x.toFixed(1)}" y="${(b.y+13).toFixed(1)}" font-size="15" fill="#384057" font-weight="700">${a.id}</text><text x="${b.x.toFixed(1)}" y="${(b.y+29).toFixed(1)}" font-size="13" fill="#7f869d">${sub(a)}</text></g>`;}).join('');
  const hubs=hubPts.map(({v,x,y},i)=>{const b=hubBoxes[i];return `<g><title>${safe(v.name)} · ${safe(v.place||v.location)} (illustrative hub)</title><rect x="${x-5}" y="${y-5}" width="10" height="10" rx="1" transform="rotate(45 ${x} ${y})" fill="#dadeea" stroke="#76838f"/>${b?`<text x="${(b.x+4).toFixed(1)}" y="${(b.y+11).toFixed(1)}" fill="#8c94aa" font-size="12" letter-spacing="1">${v.id.toUpperCase()} HUB</text>`:''}</g>`;}).join('');
  const all=[...state.airports,...state.suppliers],west=all.filter(p=>p.lon<-30),east=all.filter(p=>p.lon>=-30);
  const oceanSpots=network.extended?[{name:'PACIFIC',lon:-131,lat:31},{name:'ATLANTIC',lon:west.length&&east.length?(Math.max(...west.map(p=>p.lon))+Math.min(...east.map(p=>p.lon)))/2:-40,lat:38}]:[{name:'PACIFIC',lon:-127,lat:33},{name:'ATLANTIC',lon:-69,lat:32}];
  const busy=[...markerBoxes,...airportBoxes,...hubBoxes];
  const oceans=oceanSpots.map(o=>{const {x,y}=xy(o),w=textWidth(o.name,13)+o.name.length*2,box={x:x-w/2,y:y-11,w,h:14};const clear=box.x>=W.x&&box.x+w<=W.x+W.w&&box.y>=W.y&&box.y+14<=W.y+W.h&&!busy.some(t=>Math.min(box.x+box.w,t.x+t.w)>Math.max(box.x,t.x)&&Math.min(box.y+box.h,t.y+t.h)>Math.max(box.y,t.y));return clear?`<text x="${x.toFixed(1)}" y="${y.toFixed(1)}" text-anchor="middle" fill="#b2b7c5" font-size="13" letter-spacing="2">${o.name}</text>`:'';}).join('');
  const base=network.extended
    ?`<path d="${network.graticule}" fill="none" stroke="#e4e7f0" stroke-width=".8"/><path d="${flatPath(WORLD_LAND,project,WORLD_SCALE,true)}" fill="#e2e5f0" fill-rule="evenodd" stroke="#cdd2e1" stroke-width=".8" stroke-linejoin="round"/><path d="${flatPath(WORLD_BORDERS,project,WORLD_SCALE)}" fill="none" stroke="#f7f8fb" stroke-width=".8" stroke-linejoin="round"/>`
    :`<path d="${GRATICULE}" fill="none" stroke="#e4e7f0" stroke-width=".8"/><path d="${LAND}" fill="#e2e5f0" stroke="#cdd2e1" stroke-width="1" stroke-linejoin="round"/><path d="${BORDERS}" fill="none" stroke="#f7f8fb" stroke-width="1" stroke-linejoin="round"/>`;
  const scaleKm=[100,200,500,1000,2000].reduce((best,km)=>km*network.kmPx<=140?km:best,100),scalePx=scaleKm*network.kmPx;
  const region=network.extended?'the United States and Europe':'the contiguous United States';
  $('#map').innerHTML=`<svg viewBox="0 0 850 420" role="img" aria-label="Map of ${region} showing airports, supplier hubs, and firm and conditional SAF allocations"><defs><marker id="flight-arrow" viewBox="0 0 10 10" refX="12" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#6f7895"/></marker><radialGradient id="storm"><stop stop-color="#ceae76" stop-opacity=".22"/><stop offset="1" stop-color="#ceae76" stop-opacity="0"/></radialGradient><clipPath id="map-clip"><rect x="0" y="0" width="850" height="392"/></clipPath></defs><g clip-path="url(#map-clip)">${base}</g>${oceans}${weather}${mapLayer==='flights'?flightArcs:routes+hubs}${nodes}<text x="30" y="404" fill="#9aa0b2" font-size="13">${mapLayer==='flights'?'Flight routes: great-circle paths, SAF uplift at departure':'Physical supply: supplier hub to origin airport'} · ${network.extended?'Overview projection · Natural Earth outlines':'Albers equal-area'} · Illustrative data</text><g transform="translate(${(826-scalePx).toFixed(1)},376)"><rect x="-6" y="-17" width="${(scalePx+12).toFixed(1)}" height="27" rx="3" fill="#f8f9fc" opacity=".85"/><path d="M0,0V6H${scalePx.toFixed(1)}V0" fill="none" stroke="#9aa0b2" stroke-width="1.2"/><text x="${(scalePx/2).toFixed(1)}" y="-4" text-anchor="middle" fill="#9aa0b2" font-size="12">${num(scaleKm,0)} km</text></g></svg>`;
}

function renderRouteFocus(){
  if(!result.flightRows.some(f=>f.id===selectedFlight))selectedFlight=result.flightRows[0]?.id;
  const f=result.flightRows.find(f=>f.id===selectedFlight);
  const originSelect=$('#route-origin'),destSelect=$('#route-destination');
  originSelect.innerHTML=[...new Set(state.flights.map(f=>f.origin))].map(id=>`<option value="${id}" ${f?.origin===id?'selected':''}>${id} · ${state.airports.find(a=>a.id===id).name}</option>`).join('');
  destSelect.innerHTML=result.flightRows.filter(r=>r.origin===f?.origin).map(r=>`<option value="${r.id}" ${r.id===f?.id?'selected':''}>${r.destination} · ${safe(r.airline)} · ${r.id}</option>`).join('');
  if(!f){renderFallback();$('#route-focus-content').innerHTML='<p class="empty-routes">No routes yet. Add a route in Supply & constraints to begin.</p>';return;}
  const origin=state.airports.find(a=>a.id===f.origin),dest=state.airports.find(a=>a.id===f.destination);
  const vendors=[...new Set(state.lanes.filter(l=>l.airport===f.origin).map(l=>l.supplier))].map(id=>state.suppliers.find(v=>v.id===id).name);
  $('#route-focus-content').innerHTML=`<div class="route-journey"><div class="journey-end"><span class="eyebrow">01 / SUPPLY & UPLIFT</span><h3>${f.origin} <small>${safe(origin.name)}</small></h3><p>${vendors.join(' · ')||'No supply lane'}</p><div class="journey-stat"><span>Origin disruption <b>${f.originRisk}%</b></span><span>Supply delivery failure <b>${origin.delivery}%</b></span></div><p class="journey-weather">${safe(origin.hazard)} · ${origin.wind} kt</p></div><div class="journey-decision"><span class="eyebrow">02 / OUTBOUND ROUTE</span><div class="journey-arrow">${f.origin} <span>→</span> ${f.destination}</div><span class="status ${statusClass(f.status)}">${f.status}</span><div class="journey-quantities"><b>${vol(f.firm)} US gal <small>firm</small></b><b>${vol(f.hold)} US gal <small>flexible</small></b></div><p>${safe(f.airline)} · ${f.id}<br>${num(f.routeRisk,1)}% combined route risk</p></div><div class="journey-end destination"><span class="eyebrow">03 / DESTINATION OUTLOOK</span><h3>${f.destination} <small>${safe(dest.name)}</small></h3><p>${safe(dest.hazard)} · ${dest.wind} kt assumed wind</p><div class="journey-stat"><span>Destination disruption <b>${f.destinationRisk}%</b></span><span>En-route disruption <b>${f.enroute}%</b></span></div><p class="journey-weather">Departure ${formatHour(f.depart)}<br>Arrival ${formatHour(f.depart+f.duration)}</p></div></div><details class="route-reason"><summary>Why ${f.origin} → ${f.destination} receives this recommendation</summary><ul>${f.reasons.map(r=>`<li>${safe(volumeText(r))}</li>`).join('')}</ul><p>Destination weather is a demonstration daily outlook, not an arrival-hour forecast. Destination risk represents the chance of preventing planned origin uplift; a diversion after takeoff does not undo SAF already used.</p></details>`;
}
function renderFallback(){
 renderTradeoff();
 const f=result.flightRows.find(f=>f.id===selectedFlight),c=compareFallback(state,f,fallback);
 $('#fallback-route').textContent=f?'· '+f.origin+' → '+f.destination:'';
 const metric=(title,value,detail)=>`<div class="fallback-metric"><span>${title}</span><strong>${value}</strong><small>${detail}</small></div>`;
 $('#fallback-results').innerHTML=`<div class="fallback-summary">${safe(c.reason)} ${!c.blocked?`Modelled route disruption: <b>${num(100*(1-c.p),1)}%</b>. Comparing <b>${vol(c.q)} US gal</b> of ${vol(c.allocated)} US gal planned SAF.`:''}</div><div class="fallback-metrics">${metric('Net fuel expense saving if operated',money(c.netIfOperates),'SAF premium less switching fees; excludes future SAF use costs')}${metric('Expected procurement cash benefit',money(c.cashBenefit),fallback.stage==='owned'?'Negative: extra conventional-fuel spend; owned SAF is not refunded':'Risk-weighted avoided purchases, less fees; future SAF spend excluded')}${metric('SAF set aside for later',vol(c.q)+' US gal',fallback.stage==='owned'?'Retained inventory; not a cash refund':'Potential supply preserved; supplier availability not guaranteed')}${metric('Expected permanent loss avoided',vol(c.wasteAvoided,1)+' US gal','Only under your explicit loss assumption; not all disrupted supply')}</div><div class="fallback-detail-grid"><div><h3>Fuel cost comparison</h3><div class="comparison-line"><span>SAF tranche if operated</span><b>${money(c.safCost)}</b></div><div class="comparison-line"><span>Equivalent conventional fuel</span><b>${money(c.jetCost)}</b></div><div class="comparison-line"><span>Switching fees charged now</span><b>${money(c.fees)}</b></div><div class="comparison-line"><span>Expected net fuel expense saving</span><b>${money(c.expectedPremium)}</b></div><p>Weighted SAF quote: ${rate(c.safPrice)}/US gal. Purchases are modelled only if the flight proceeds; fees apply regardless. Existing non-refundable commitments must be entered as fees. Fuel availability is assumed for both choices; supply delivery failure is excluded from this comparison.</p></div><div><h3>GHG opportunity, counted once</h3><div class="comparison-line"><span>Expected current-route reduction deferred</span><b>${num(c.ghgDeferred,1)} tCO₂e</b></div><div class="comparison-line"><span>Potential reduction from later SAF use</span><b>${num(c.futureOpportunity,1)} tCO₂e</b></div><div class="comparison-line"><span>SAF at risk of not being used as planned</span><b>${vol(c.atRisk)} US gal</b></div><p>Later use is a separate opportunity, not an additional credited reduction or proof of a net GHG gain. No reduction is booked until SAF substitutes fossil fuel. The original strategy may also reuse unused fuel; its future use is not modelled.</p></div></div><details class="fallback-assumptions"><summary>Calculation & interpretation</summary><p>q = allocated SAF × switch share. p = 1 − combined route disruption. Net fuel expense saving if operated = q × (SAF delivered price − jet price − fee). Expected saving = p × q × price difference − q × fee. For owned SAF, expected cash benefit = −p × q × jet price − q × fee. Permanent loss avoided = q × (1 − p) × loss fraction, assuming held supply has no physical loss. This separate physical-loss scenario assumes pre-positioned SAF and is not monetized in the conditional-purchase cash model. It does not guarantee zero wastage. Current GHG reduction deferred = p × q × lifecycle saving per US gallon; future opportunity = q × later-use share × lifecycle saving per US gallon. These are scenario estimates, not an optimized reallocation. A disruption after fueling does not automatically destroy fuel or its lifecycle benefit.</p><p>Lifecycle and fuel context: <a href="https://www.icao.int/CORSIA/fuels-lifecycle" target="_blank" rel="noreferrer">ICAO lifecycle methodology ↗</a> · <a href="https://www.iata.org/en/programs/sustainability/reports/saf-handbook/section-2.1" target="_blank" rel="noreferrer">IATA SAF fuel compatibility ↗</a></p></details>`;
}
function syncTradeoff(){for(const [k,v] of Object.entries(tradeoff))$('#tradeoff-'+k).value=v;}
function tradeoffResult(){return optimizeTradeoff(state,result.flightRows.find(f=>f.id===selectedFlight),fallback,tradeoff);}
function renderTradeoff(){
 const f=result.flightRows.find(f=>f.id===selectedFlight),t=tradeoffResult();
 $('#economics-route-label').textContent=f?`Selected route: ${f.origin} → ${f.destination} · ${f.airline} · ${f.id}`:'No route selected. Add a route in Routes.';
 $('#tradeoff-route').textContent=f?'· '+f.origin+' → '+f.destination:'';
 for(const key of ['budget','target','carbonPrice'])$('#tradeoff-'+key+'-label').hidden=key!==({budget:'budget',target:'target',value:'carbonPrice'}[tradeoff.mode]);
 $('#tradeoff-context').textContent=`Uses fuel assumptions below: jet ${rate(fallback.jetPrice)}/US gal · switching fee ${rate(fallback.fee)}/US gal · ${fallback.stage==='owned'?'SAF already owned':fallback.stage==='loaded'?'fuel loaded / commingled':'SAF not purchased'}${fallback.locked?' · switching locked by contract':''}.`;
 if(!t.available){$('#tradeoff-results').innerHTML=`<p class="tradeoff-message">${safe(t.reason)}</p>`;return;}
 const r=t.recommendation,metric=(label,value,detail)=>`<div class="fallback-metric"><span>${label}</span><strong>${value}</strong><small>${detail}</small></div>`;
 const metricHtml=r?`<div class="fallback-metrics">${metric('Retain SAF / use conventional',vol(r.saf)+' / '+vol(r.jet)+' US gal','Only the '+vol(t.q)+' US gal allocated tranche')}${metric('Expected new cash spend',money(r.cash),money(t.allSaf.cash-r.cash)+' saving vs retaining all SAF')}${metric('Expected lifecycle emissions',num(r.emissions,1)+' tCO₂e','Selected tranche only; remaining aircraft fuel excluded')}${metric('Expected GHG reduction',num(r.reduction,1)+' tCO₂e','Against equivalent conventional fuel; no future-use credit')}</div>`:'';
 const rows=[...t.points,...(r?[{...r,recommended:true}]:[])].sort((a,b)=>a.saf-b.saf);
 const maxCash=Math.max(1,...rows.map(v=>v.cash)),maxGHG=Math.max(1,...rows.map(v=>v.emissions));
 const chart=`<div class="tradeoff-chart"><svg viewBox="0 0 680 260" role="img" aria-label="Fuel mix trade-off: horizontal axis expected cash spend, vertical axis expected lifecycle emissions. Table below provides exact values."><path d="M75 20 V210 H650" fill="none" stroke="#9ca2b5"/><text x="360" y="252" text-anchor="middle">Expected new cash spend ($)</text><text x="16" y="120" transform="rotate(-90 16 120)" text-anchor="middle">Lifecycle emissions (tCO₂e)</text><text x="72" y="230">$0</text><text x="645" y="230" text-anchor="end">${money(maxCash)}</text><text x="68" y="24" text-anchor="end">${num(maxGHG,1)}</text><text x="65" y="210" text-anchor="end">0</text><polyline points="${t.points.map(v=>(75+v.cash/maxCash*565)+','+(210-v.emissions/maxGHG*180)).join(' ')}" fill="none" stroke="#55679e" stroke-width="3"/>${rows.map(v=>`<circle cx="${75+v.cash/maxCash*565}" cy="${210-v.emissions/maxGHG*180}" r="${v.recommended?8:4}" fill="${v.recommended?'#292d35':'#8895bb'}"><title>${v.recommended?'Recommended: ':''}${num(v.share,1)}% SAF retained, ${money(v.cash)}, ${num(v.emissions,1)} tCO₂e</title></circle>`).join('')}</svg><p>Dark point = recommended mix. Lower emissions and lower cost are preferable. Percentages refer to the allocated SAF tranche.</p></div>`;
 $('#tradeoff-results').innerHTML=`<div class="tradeoff-message ${r?'':'unmet'}"><b>${r?'Recommended: retain '+num(r.share,1)+'% of allocated SAF.':'Constraint not met.'}</b> ${r?(t.locked?'Contract lock prevents switching.':tradeoff.mode==='budget'?'Maximum expected reduction within your cash ceiling.':tradeoff.mode==='target'?'Lowest expected cash spend meeting your reduction target.':'Lowest combined cash and internal carbon value.') :safe(t.reason)}${t.p===0?' Route operation probability is zero; no tomorrow-use GHG benefit is claimed.':''}</div>${metricHtml}<div class="tradeoff-body">${chart}<div class="tradeoff-decision"><span class="eyebrow">THE PRICE OF REDUCTION</span><h3>${t.costPerTonne===null?'No expected abatement':money(t.costPerTonne)+' / tCO₂e'}</h3><p>Incremental expected cash to retain SAF instead of switching, including avoided switching fees. Negative means SAF retention saves new cash under these assumptions.</p>${r?`<p>GHG reduction given up vs all SAF: <b>${num(t.allSaf.reduction-r.reduction,1)} tCO₂e</b>.</p>${tradeoff.mode==='value'?`<p>Cash + internal carbon value: <b>${money(r.cash+tradeoff.carbonPrice*r.emissions)}</b>.</p>`:''}<button class="btn dark" id="apply-tradeoff" ${t.locked?'disabled':''}>Apply mix to fuel comparison ↓</button>`:''}</div></div><div class="table-scroll"><table><thead><tr><th>SAF retained</th><th>Expected cash</th><th>Lifecycle GHG</th><th>GHG reduction</th></tr></thead><tbody>${rows.map(v=>`<tr class="${v.recommended?'tradeoff-selected':''}"><td>${num(v.share,1)}%${v.recommended?' · Recommended':''}</td><td>${money(v.cash)}</td><td>${num(v.emissions,1)} tCO₂e</td><td>${num(v.reduction,1)} tCO₂e</td></tr>`).join('')}</tbody></table></div>`;
 const button=$('#apply-tradeoff');if(button)button.onclick=()=>{fallback.share=100-r.share;syncFallback();renderFallback();$('#fallback-card').scrollIntoView({behavior:'smooth'});toast('Recommended mix applied to the comparison. Supply allocations are unchanged.');};
}
function syncFallback(){for(const [k,v]of Object.entries(fallback)){const el=$('#fallback-'+k);if(k==='locked')el.checked=v;else el.value=isPrice(k)?Number(toDisplay(k,v).toFixed(4)):v;}}
function renderFlightRows(){
  $('#flight-rows').innerHTML=result.flightRows.map(f=>`<tr data-flight="${f.id}" role="button" tabindex="0" aria-label="Inspect route ${f.origin} to ${f.destination} ${f.id}"><td><b>${safe(f.airline)}</b><small class="route-small">${f.id} · daily route group</small></td><td><b>${f.origin}</b> <span class="route-small">SAF at origin</span></td><td><b>→ ${f.destination}</b><small class="route-small">${safe(f.destinationHazard)} · ${f.destinationRisk}%</small></td><td><span class="risk"><i class="risk-dot ${f.routeRisk>state.tolerance?'high':''}"></i>${num(f.routeRisk,1)}%</span></td><td>${vol(f.firm)} US gal <span class="muted">/</span> ${vol(f.hold)} US gal</td><td><span class="status ${statusClass(f.status)}">${f.status}</span></td></tr>`).join('');
}
function renderFlightInputs(){
  $('#flight-inputs').innerHTML=state.flights.map((f,i)=>`<tr><td><input class="airline-input" aria-label="Airline ${f.id}" data-group="flights" data-index="${i}" data-key="airline" maxlength="60" value="${safe(f.airline)}"><small class="route-small">${f.id}</small></td>${['origin','destination'].map(k=>`<td><select aria-label="${f.id} ${k}" data-group="flights" data-index="${i}" data-key="${k}">${state.airports.map(a=>`<option value="${a.id}" ${f[k]===a.id?'selected':''}>${a.id}</option>`).join('')}</select></td>`).join('')}<td>${input('flights',i,'target',f.target)}</td><td>${input('flights',i,'enroute',f.enroute)}</td><td><select aria-label="${f.id} departure" data-group="flights" data-index="${i}" data-key="depart">${Array.from({length:24},(_,h)=>`<option value="${24+h}" ${f.depart===h+24?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select></td><td>${input('flights',i,'duration',f.duration)}</td><td><button class="text-btn remove-route" data-remove-route="${f.id}" aria-label="Remove ${f.id}">×</button></td></tr>`).join('');
}

function input(group,i,key,value,extra=''){const [min,max]=bounds[key],unit=isVolume(key)?' (US gal)':isPrice(key)?' ($/US gal)':'';return `<input aria-label="${safe(group+' '+i+' '+key+unit)}" data-group="${group}" data-index="${i}" data-key="${key}" type="number" min="${toDisplay(key,min)}" max="${toDisplay(key,max)}" step="${isPrice(key)?'0.01':isVolume(key)?'0.01':key==='ci'?'0.1':'1'}" value="${Number(toDisplay(key,value).toFixed(isPrice(key)?4:2))}" ${extra}>`}

function renderInputs(){
  renderFlightInputs();
  $('#supplier-inputs').innerHTML=state.suppliers.map((v,i)=>`<div class="supplier-edit"><h3>${v.name}</h3><p>${v.location} · Illustrative offer</p><label>Available SAF (US gal) ${input('suppliers',i,'supply',v.supply)}</label><label>Purchase price ($/US gal) ${input('suppliers',i,'price',v.price)}</label><label>Lifecycle CI (gCO₂e/MJ) ${input('suppliers',i,'ci',v.ci)}</label></div>`).join('');
  $('#airport-inputs').innerHTML=state.airports.map((a,i)=>`<tr><td><b>${a.id}</b></td><td><select aria-label="${a.id} weather outlook" data-group="airports" data-index="${i}" data-key="hazard">${hazards.map(h=>`<option ${a.hazard===h?'selected':''}>${h}</option>`).join('')}</select></td><td>${input('airports',i,'wind',a.wind)}</td><td>${input('airports',i,'risk',a.risk)}</td><td>${input('airports',i,'delivery',a.delivery)}</td><td>${input('airports',i,'demand',a.demand)}</td><td><select aria-label="${a.id} receive by" data-group="airports" data-index="${i}" data-key="need">${Array.from({length:24},(_,h)=>`<option value="${24+h}" ${a.need===24+h?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select></td></tr>`).join('');
  $('#lane-inputs').innerHTML=state.lanes.map((l,i)=>{const deadline=state.airports.find(a=>a.id===l.airport).need-l.lead;return `<tr><td>${state.suppliers.find(v=>v.id===l.supplier).name} <span class="muted">→</span> <b>${l.airport}</b></td><td>${input('lanes',i,'lead',l.lead)}</td><td>${input('lanes',i,'freight',l.freight)}</td><td>${input('lanes',i,'capacity',l.capacity)}</td><td>${deadline<0?'Before planning day':formatHour(deadline)}</td><td><span class="status ${deadline>=state.review?'commit':'unallocated'}">${deadline>=state.review?'Yes':'No'}</span></td></tr>`}).join('');
}

function openDrawer(id){selected=id;lastFocus=document.activeElement;renderDrawer();$('#drawer').hidden=false;$('#drawer-overlay').hidden=false;$('#drawer').setAttribute('role','dialog');$('#drawer').setAttribute('aria-modal','true');$('#close-drawer').focus();document.body.style.overflow='hidden'}
function closeDrawer(){selected=null;$('#drawer').hidden=true;$('#drawer-overlay').hidden=true;document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
function renderDrawer(){const a=result.rows.find(a=>a.id===selected),idx=state.airports.findIndex(a=>a.id===selected);if(!a)return;
  $('#drawer-content').innerHTML=`<h2>${a.id} <span style="font-weight:400;color:#9197a9;font-size:19px">/ ${safe(a.name)}</span></h2><p class="sub">${safe(a.hazard)} · ${a.wind} kt assumed wind</p><span class="status ${statusClass(a.status)}">${a.status}</span><div class="drawer-metrics"><div><strong>${vol(a.firm)} US gal</strong><span>Firm allocation</span></div><div><strong>${vol(a.hold)} US gal</strong><span>Conditional allocation</span></div></div><h3>Why this recommendation</h3><ul>${a.reasons.map(r=>`<li>${safe(volumeText(r))}</li>`).join('')}</ul><h3>Test the assumption</h3><label>Operational disruption (%) ${input('airports',idx,'risk',a.risk)}</label><label>Delivery failure (%) ${input('airports',idx,'delivery',a.delivery)}</label><p>These are scenario assumptions, not calibrated weather forecasts. Wind and hazard labels do not directly alter the risk inputs.</p><h3>Selected supply</h3>${a.allocations.length?a.allocations.map(l=>`<div class="allocation-detail"><strong>${state.suppliers.find(v=>v.id===l.supplier).name}</strong> · ${vol(l.quantity)} US gal ${l.kind==='firm'?'firm':'conditional'}<small>${rate(l.price)}/US gal delivered · Release by ${formatHour(l.deadline)}</small></div>`).join(''):'<p>No feasible allocation within the current guardrails.</p>'}<h3>Lifecycle savings from firm supply</h3><p><strong>${num(a.benefit,1)} tCO₂e</strong> if all firm volume substitutes conventional fuel.<br><strong>${num(a.expected,1)} tCO₂e</strong> probability-weighted for use tomorrow.<br>Conditional holds excluded; no contrail or certified credit claims.</p><button class="btn light" id="drawer-edit" style="margin-top:22px">Edit all delivery constraints ↗</button>`;
}

