document.addEventListener('click',e=>{const jump=e.target.closest('[data-jump]');if(e.target.closest('.brand')){e.preventDefault();changeTab('overview');window.scrollTo({top:0,behavior:'auto'});}if(jump){const target=document.getElementById(jump.dataset.jump);changeTab(target?.closest('.tab-panel')?.id||'overview');target?.scrollIntoView({behavior:'auto',block:'start'});}const flight=e.target.closest('[data-flight]');if(flight){selectedFlight=flight.dataset.flight;renderRouteFocus();renderFallback();renderMap();changeTab('routes');$('.route-focus').scrollIntoView({behavior:'auto',block:'start'});}const nav=e.target.closest('[data-tab]');if(nav)changeTab(nav.dataset.tab);const row=e.target.closest('[data-airport]');if(row)openDrawer(row.dataset.airport);if(e.target.closest('#drawer-edit')){closeDrawer();changeTab('supply')}});
document.addEventListener('keydown',e=>{const row=e.target.closest('[data-airport]');if(row&&['Enter',' '].includes(e.key)){e.preventDefault();openDrawer(row.dataset.airport)}const flight=e.target.closest('[data-flight]');if(flight&&['Enter',' '].includes(e.key)){e.preventDefault();selectedFlight=flight.dataset.flight;renderRouteFocus();renderFallback();renderMap();changeTab('routes');$('.route-focus').scrollIntoView({behavior:'auto'});}if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&!$('#drawer').hidden){const els=[...$('#drawer').querySelectorAll('button,input,select,[tabindex="0"]')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
for(const key of ['budget','flex','tolerance'])$('#'+key).addEventListener('input',e=>{state[key]=Number(e.target.value);recalc()});
$('#review').addEventListener('change',e=>{state.review=Number(e.target.value);recalc();if(!$('#supply').hidden||!$('#routes').hidden)renderInputs()});
$('#scenario').addEventListener('change',e=>{if(e.target.value!=='custom')applyScenario(state,e.target.value);else state.scenario='custom';recalc();renderInputs()});
$('#plan-date').addEventListener('change',e=>{if(e.target.value)state.date=e.target.value;else e.target.value=state.date;toast('Delivery day updated. Demonstration weather is unchanged.');});
document.addEventListener('input',e=>{const t=e.target;if(!t.dataset.group||t.type!=='number'||t.value.trim()==='')return;const {group,index,key}=t.dataset;const v=Number(t.value);if(!Number.isFinite(v)||!bounds[key])return;state[group][index][key]=Math.min(bounds[key][1],Math.max(bounds[key][0],fromDisplay(key,v)));state.scenario='custom';$('#scenario').value='custom';result=plan(state);renderOverview();});
document.addEventListener('change',e=>{const t=e.target;if(!t.dataset.group)return;const {group,index,key}=t.dataset;let v=t.value;if(['origin','destination'].includes(key)){if(!state.airports.some(a=>a.id===v))return;const other=key==='origin'?'destination':'origin';if(state[group][index][other]===v){t.value=toDisplay(key,state[group][index][key]);toast('Origin and destination must be different.');return;}}else if(key==='airline'){v=v.trim().slice(0,60)||'Demo airline';}else if(key!=='hazard'){if(t.value.trim()===''||!Number.isFinite(Number(v))){t.value=toDisplay(key,state[group][index][key]);return;}const [min,max]=bounds[key];v=Math.min(max,Math.max(min,fromDisplay(key,Number(v))));}state[group][index][key]=v;state.scenario='custom';$('#scenario').value='custom';recalc();if(!$('#supply').hidden||!$('#routes').hidden)renderInputs()});
for(const key of ['baseline','lhv'])$('#'+key).addEventListener('change',e=>{const v=Number(e.target.value);if(e.target.value.trim()===''||!Number.isFinite(v)){e.target.value=state[key];return;}state[key]=Math.min(bounds[key][1],Math.max(bounds[key][0],v));e.target.value=state[key];recalc()});
$('#help').onclick=()=>changeTab('method');$('#edit-all').onclick=()=>changeTab('supply');$('.return-overview').onclick=()=>changeTab('overview');$('#close-drawer').onclick=closeDrawer;$('#drawer-overlay').onclick=closeDrawer;$('#export').onclick=exportBrief;
$('#reset').onclick=()=>{resetSupplier();resetCompliance();fallback=fallbackDefaults();tradeoff=tradeoffDefaults();syncTradeoff();syncFallback();state=demoState();syncControls();recalc();renderInputs();try{localStorage.removeItem('aerocommit-v2')}catch{}toast('Demonstration restored.');};
$('#save').onclick=()=>{try{localStorage.setItem('aerocommit-v2',JSON.stringify({...state,fallback,tradeoff,supplier:getSupplier(),compliance:getCompliance()}));toast('Scenario saved in this browser.')}catch{toast('Browser storage is unavailable; export the brief instead.')}};
// Restore only validated values into the known demo schema; no arbitrary markup or fields.
const evidenceGroup=status=>['Physical supply listed','Reported offering'].includes(status)?'supply':['Occasional / operator use','Historical delivery agreement','Batch delivery'].includes(status)?'occasional':'project';
function addDirectoryAirport(id,notify=true){
 const a=safAirports.find(a=>a.id===id);if(!a||state.airports.some(b=>b.id===id))return;
 const n=state.airports.length-6;
 state.airports.push({id:a.id,name:a.name,hazard:'Not configured',risk:100,delivery:100,wind:0,demand:0,need:42,lon:a.lon,lat:a.lat});
 state.suppliers.forEach(v=>state.lanes.push({supplier:v.id,airport:id,lead:0,freight:0,capacity:0}));
 if(notify){state.scenario='custom';$('#scenario').value='custom';recalc();renderInputs();renderDirectory();toast(id+' added. Configure risk, demand and delivery lanes before planning.');}
}
function directoryResults(){const q=$('#airport-search').value.trim().toLowerCase(),region=$('#airport-region').value,country=$('#airport-country').value,kind=$('#airport-evidence').value;return safAirports.filter(a=>(!region||a.region===region)&&(!country||a.country===country)&&(!kind||a.evidence.some(e=>evidenceGroup(e.status)===kind))&&(!q||[a.id,a.icao,...a.aliases,a.name,countryName(a.country),...a.evidence.map(e=>e.provider)].join(' ').toLowerCase().includes(q)));}
function renderDirectory(){
 const all=safAirports,us=all.filter(a=>a.region==='US').length;
 $('#directory-metrics').innerHTML=[[all.length,'Airports in directory'],[us,'United States'],[all.length-us,'Europe / ECAC'],[new Set(all.map(a=>a.country)).size,'Countries']].map(([n,t])=>`<div class="metric"><div class="number">${n}</div><p>${t}</p></div>`).join('');
 const rows=directoryResults();$('#directory-count').textContent=rows.length+' of '+all.length+' airports · sources checked '+checkedOn;
 $('#directory-rows').innerHTML=rows.length?rows.map(a=>`<tr><td><b class="directory-code">${safe(a.id)}</b> <span class="muted">${safe(a.icao)}</span><p>${safe(a.name)}</p></td><td>${safe(countryName(a.country))}<small>${a.region==='US'?'United States':'Europe / ECAC'}</small></td><td>${a.evidence.map(e=>`<div class="directory-evidence"><span class="status ${evidenceGroup(e.status)==='supply'?'commit':'flexible'}">${safe(e.status)}</span><div>${safe(e.provider)}${e.reservation?' · Advance reservation noted':''}</div><a href="${safe(e.url)}" target="_blank" rel="noopener noreferrer">${safe(e.source)} ↗</a><small>Source record / announcement: ${e.date||'Date not stated'} · Live stock unknown</small></div>`).join('')}</td><td><button class="btn light" data-directory-add="${safe(a.id)}" ${state.airports.some(b=>b.id===a.id)?'disabled':''}>${state.airports.some(b=>b.id===a.id)?'In scenario':'Add to scenario +'}</button></td></tr>`).join(''):'<tr><td colspan="4">No matching airports. Try another country or search term.</td></tr>';
}
try{const saved=JSON.parse(localStorage.getItem('aerocommit-v2')||'null');if(saved){if(Array.isArray(saved.airports))saved.airports.forEach(a=>{if(!state.airports.some(b=>b.id===a.id)&&safAirports.some(b=>b.id===a.id))addDirectoryAirport(a.id,false);});if(saved.tradeoff){if(['budget','target','value'].includes(saved.tradeoff.mode))tradeoff.mode=saved.tradeoff.mode;for(const k of ['budget','target','carbonPrice']){const v=saved.tradeoff[k];if(typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=(k==='budget'?100000000:1000000))tradeoff[k]=v;}}if(saved.fallback){for(const k of ['jetPrice','share','fee','loss','reuse']){const v=saved.fallback[k],max=['jetPrice','fee'].includes(k)?20000:100;if(typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max)fallback[k]=v;}if(['unpurchased','owned','loaded'].includes(saved.fallback.stage))fallback.stage=saved.fallback.stage;fallback.locked=saved.fallback.locked===true;}for(const k of ['budget','flex','tolerance','review','baseline','lhv']){const limits={budget:[0,1500000],flex:[0,100],tolerance:[0,100],review:[24,36],...bounds}[k];if(typeof saved[k]==='number'&&saved[k]>=limits[0]&&saved[k]<=limits[1])state[k]=saved[k];}if(/^\d{4}-\d{2}-\d{2}$/.test(saved.date))state.date=saved.date;if(Array.isArray(saved.flights)&&saved.flights.length<=30){state.flights=saved.flights.filter(f=>typeof f.id==='string'&&/^R[0-9]+$/.test(f.id)&&state.airports.some(a=>a.id===f.origin)&&state.airports.some(a=>a.id===f.destination)&&f.origin!==f.destination&&['target','enroute','depart','duration'].every(k=>typeof f[k]==='number'&&f[k]>=bounds[k][0]&&f[k]<=bounds[k][1])).map(f=>({id:f.id,airline:String(f.airline).slice(0,60),origin:f.origin,destination:f.destination,target:f.target,enroute:f.enroute,depart:f.depart,duration:f.duration}));state.flights=state.flights.filter((f,i,arr)=>arr.findIndex(g=>g.id===f.id)===i);}for(const group of ['airports','suppliers','lanes'])state[group].forEach((obj,i)=>{for(const key of Object.keys(obj)){const v=saved[group]?.[i]?.[key];if(bounds[key]&&typeof v==='number'&&v>=bounds[key][0]&&v<=bounds[key][1])obj[key]=v;else if(key==='hazard'&&hazards.includes(v))obj[key]=v;}});state.scenario='custom';}}catch{}
$('#route-origin').onchange=e=>{selectedFlight=state.flights.find(f=>f.origin===e.target.value)?.id;renderRouteFocus();renderFallback();renderMap();};
$('#route-destination').onchange=e=>{selectedFlight=e.target.value;renderRouteFocus();renderFallback();renderMap();};
$('#flight-layer').onclick=()=>{mapLayer='flights';$('#flight-layer').classList.add('active');$('#supply-layer').classList.remove('active');renderMap();};
$('#supply-layer').onclick=()=>{mapLayer='supply';$('#supply-layer').classList.add('active');$('#flight-layer').classList.remove('active');renderMap();};
$('#edit-routes').onclick=()=>{$('#route-editor').open=true;$('#route-editor').scrollIntoView({behavior:'auto',block:'start'});};
$('#add-route').onclick=()=>{if(state.flights.length>=30){toast('This prototype supports up to 30 route groups.');return;}const n=Math.max(100,...state.flights.map(f=>Number(f.id.slice(1))))+1;state.flights.push({id:'R'+n,airline:'New airline (demo)',origin:'SFO',destination:'JFK',target:20,enroute:5,depart:44,duration:6});state.scenario='custom';$('#scenario').value='custom';recalc();renderFlightInputs();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-remove-route]');if(b){state.flights=state.flights.filter(f=>f.id!==b.dataset.removeRoute);state.scenario='custom';$('#scenario').value='custom';recalc();renderFlightInputs();}});
for(const key of ['jetPrice','share','fee','loss','reuse'])$('#fallback-'+key).addEventListener('input',e=>{if(e.target.value.trim()==='')return;const v=Number(e.target.value);if(!Number.isFinite(v))return;fallback[key]=Math.min(['jetPrice','fee'].includes(key)?20000:100,Math.max(0,fromDisplay(key,v)));renderFallback();});
for(const key of ['jetPrice','share','fee','loss','reuse'])$('#fallback-'+key).addEventListener('change',()=>syncFallback());
$('#fallback-stage').onchange=e=>{fallback.stage=e.target.value;renderFallback();};
$('#fallback-locked').onchange=e=>{fallback.locked=e.target.checked;renderFallback();};
$('#compare-disrupted').onclick=()=>{const f=[...result.flightRows].filter(f=>f.firm+f.hold>0).sort((a,b)=>b.routeRisk-a.routeRisk)[0];if(f){selectedFlight=f.id;renderRouteFocus();renderMap();renderFallback();}else toast('No allocated route is available to compare.');};
$('#tradeoff-mode').onchange=e=>{tradeoff.mode=e.target.value;renderTradeoff();};
for(const key of ['budget','target','carbonPrice']){$('#tradeoff-'+key).oninput=e=>{if(e.target.value.trim()===''||!Number.isFinite(Number(e.target.value)))return;tradeoff[key]=Math.max(0,Math.min(key==='budget'?100000000:1000000,Number(e.target.value)));renderTradeoff();};$('#tradeoff-'+key).onchange=syncTradeoff;}
try{const saved=JSON.parse(localStorage.getItem('aerocommit-v2')||'null');if(saved?.supplier)restoreSupplier(saved.supplier);if(saved?.compliance)restoreCompliance(saved.compliance);}catch{}
initSupplier({toast});
initCompliance({toast});
initTracker();
syncTradeoff();syncFallback();syncControls();recalc();renderInputs();

$('.section-tabs').addEventListener('keydown',e=>{const tabs=[...$$('.section-tab')],i=tabs.indexOf(e.target);if(i<0)return;let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();e.stopPropagation();changeTab(tabs[n].dataset.tab,false);tabs[n].focus();});
window.addEventListener('hashchange',()=>changeTab(location.hash.slice(1),false));
changeTab(location.hash.slice(1)||'overview',false);

$('#hero-motion-toggle').addEventListener('click',e=>{const paused=$('.editorial-hero').classList.toggle('motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.setAttribute('aria-label',paused?'Play cinematic motion':'Pause cinematic motion');e.currentTarget.textContent=paused?'▶  Play animation':'Ⅱ  Pause animation';});

$('#airport-country').innerHTML+=[...new Set(safAirports.map(a=>a.country))].sort((a,b)=>countryName(a).localeCompare(countryName(b))).map(c=>`<option value="${c}">${safe(countryName(c))}</option>`).join('');
for(const id of ['airport-search','airport-region','airport-country','airport-evidence'])$('#'+id).addEventListener(id==='airport-search'?'input':'change',renderDirectory);
document.addEventListener('click',e=>{const b=e.target.closest('[data-directory-add]');if(b)addDirectoryAirport(b.dataset.directoryAdd);});
$('#directory-export').onclick=()=>{const url=URL.createObjectURL(new Blob([toCsv(directoryCsvRows(directoryResults(),checkedOn))],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='aerocommit-saf-airports-'+checkedOn+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

// Progressive enhancement: reveal the landing panels together in reading order.
const explainerGrid=document.querySelector('.explainer-grid');
const reducedPanelMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
if(explainerGrid && 'IntersectionObserver' in window && !reducedPanelMotion.matches){
  explainerGrid.classList.add('reveal-ready');
  const panelObserver=new IntersectionObserver(entries=>{
    if(entries.some(entry=>entry.isIntersecting)){
      explainerGrid.classList.add('panels-visible');
      panelObserver.disconnect();
    }
  },{threshold:0.12});
  panelObserver.observe(explainerGrid);
  reducedPanelMotion.addEventListener('change',e=>{if(e.matches){explainerGrid.classList.remove('reveal-ready');panelObserver.disconnect();}});
}
